import{_ as e,o,c as t,a5 as l}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Konado のインストール","description":"","frontmatter":{"title":"Konado のインストール","order":1},"headers":[],"relativePath":"ja/latest/tutorial/install.md","filePath":"ja/latest/tutorial/install.md","lastUpdated":1788455378000}'),r={name:"ja/latest/tutorial/install.md"};function i(n,a,d,s,h,c){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="konado-のインストール" tabindex="-1">Konado のインストール <a class="header-anchor" href="#konado-のインストール" aria-label="Permalink to &quot;Konado のインストール&quot;">​</a></h1><h2 id="必要環境" tabindex="-1">必要環境 <a class="header-anchor" href="#必要環境" aria-label="Permalink to &quot;必要環境&quot;">​</a></h2><p>最低対応バージョンは <strong>Godot 4.7.1</strong> です。</p><p>以下の Godot バージョンは開発者によってテスト済みで、正常に使用できます。</p><ul><li>4.7.1</li></ul><h3 id="プラグインのダウンロード" tabindex="-1">プラグインのダウンロード <a class="header-anchor" href="#プラグインのダウンロード" aria-label="Permalink to &quot;プラグインのダウンロード&quot;">​</a></h3><h4 id="安定版-推奨" tabindex="-1">安定版（推奨） <a class="header-anchor" href="#安定版-推奨" aria-label="Permalink to &quot;安定版（推奨）&quot;">​</a></h4><p><a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">Konado 最新リリースページ</a> にアクセスし、最新安定版のプラグイン ZIP パッケージをダウンロードしてください。安定版は十分に検証されており、安定性と信頼性が高いため、本番環境での第一候補です。</p><p>中国本土のユーザーのダウンロード体験を向上させるため、以下の最適化リンクからリソースを取得することを推奨します：<a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release リンク</a>。このリンクはダウンロード速度の改善に役立ちます。</p><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><ol><li>Godot プロジェクトディレクトリにプラグインフォルダー <code>addons</code> を作成します</li><li>release のプラグイン zip パッケージをダウンロードします</li><li><code>addons</code> ディレクトリへ展開します</li><li>Godot のプロジェクト設定でプラグインを有効にし、現在のプロジェクトを再読み込みします</li></ol><h2 id="開発チームからのメッセージ" tabindex="-1">開発チームからのメッセージ <a class="header-anchor" href="#開発チームからのメッセージ" aria-label="Permalink to &quot;開発チームからのメッセージ&quot;">​</a></h2><p>Konado プラグインのインストールが完了しました。正式に制作を始める前に、ひとつメッセージを共有します。</p><blockquote><p>「どんな業界においても、想像力に少しの知恵が加われば、それは無敵の武器になる。」</p><p>—— フィリップ・K・ディック（Philip K. Dick） 『マイノリティ・リポート』（<em>Minority Report</em>，1956）</p></blockquote><p>想像力とより良いものを追求する姿勢を持ち続け、創作の道でさらに多くの可能性を探求できますように。</p>',15)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
